import api from './api';

const WalletService = {
  getWallet: async () => {
    return api.get('/wallet');
  },
  
  getTransactions: async (params) => {
    return api.get('/wallet/transactions', { params });
  },
  
  deposit: async (amount) => {
    return api.post('/wallet/deposit', { amount });
  },
  
  withdraw: async (amount) => {
    return api.post('/wallet/withdraw', { amount });
  },
  
  transfer: async (recipientWalletNumber, amount, description) => {
    return api.post('/wallet/transfer', {
      recipientWalletNumber,
      amount,
      description
    });
  },
  
  getTransaction: async (transactionId) => {
    return api.get(`/wallet/transactions/${transactionId}`);
  }
};

export default WalletService;
